// Baked sizes, high to low; fitSize only steps through these.
const BAKED_SIZES = [36, 28, 24, 21, 20, 19, 16, 15, 14];

// Minimum legible size: no text below 14px at full size.
const MIN_SIZE = 14;

const FONT_CACHE: Record<string, { buf: Buffer; tab: number[][] }> = {};

function fontFace(face: string, size: number): { buf: Buffer; tab: number[][] } {
  const key = face + String(size);
  let f = FONT_CACHE[key];
  if (!f) {
    const d = FONT_DATA[key];
    if (!d) throw new Error("no baked font face/size: " + key);
    f = { buf: Buffer.from(d.data, "base64"), tab: d.tab };
    FONT_CACHE[key] = f;
  }
  return f;
}

function glyphIndex(ch: string): number {
  const i = CHARSET.indexOf(ch);
  if (i < 0) throw new Error("char outside baked charset: " + JSON.stringify(ch));
  return i;
}

// Exact proportional advance in pixels (sum of per-glyph advances).
function textWidth(text: string, size: number, face: string = "B"): number {
  const f = fontFace(face, size);
  let w = 0;
  for (const ch of text) w += f.tab[glyphIndex(ch)][0];
  return w;
}

function drawText(cv: Canvas, text: string, x: number, yTop: number, size: number, c: RGB, face: string = "B"): void {
  if (size < MIN_SIZE) throw new Error("text below 14px floor: " + size + " for " + JSON.stringify(text));
  const f = fontFace(face, size);
  const y0 = Math.round(yTop);
  let pen = Math.round(x);
  for (const ch of text) {
    const g = f.tab[glyphIndex(ch)];
    const adv = g[0];
    const w = g[3];
    const h = g[4];
    if (w > 0 && h > 0) {
      const xoff = g[1];
      const yoff = g[2];
      const off = g[5];
      for (let gy = 0; gy < h; gy++) {
        for (let gx = 0; gx < w; gx++) {
          const p = gy * w + gx;
          const byte = f.buf[off + (p >> 1)];
          const nib = (p & 1) === 0 ? byte >> 4 : byte & 15;
          if (nib !== 0) cv.blend(pen + xoff + gx, y0 + yoff + gy, c, nib / 15);
        }
      }
    }
    pen += adv;
  }
}

function drawTextCentered(cv: Canvas, text: string, cx: number, yTop: number, size: number, c: RGB, face: string = "B"): void {
  drawText(cv, text, cx - textWidth(text, size, face) / 2, yTop, size, c, face);
}

// Shrink the size until the text fits maxW, stepping only through baked
// sizes (never below MIN_SIZE).
function fitSize(text: string, size: number, maxW: number, face: string = "B"): number {
  let s = size;
  while (s > MIN_SIZE && textWidth(text, s, face) > maxW) {
    const next = BAKED_SIZES.filter((v) => v < s);
    if (next.length === 0) break;
    s = next[0];
  }
  return s;
}

// Word-wrap into at most maxLines lines; throws on truncation or on a
// single word wider than maxW (anti-truncation assert).
function wrapText(text: string, size: number, maxW: number, maxLines: number, face: string = "B"): string[] {
  const words = text.split(" ");
  const lines: string[] = [];
  let cur = "";
  for (const w of words) {
    if (textWidth(w, size, face) > maxW) throw new Error("word too wide: " + JSON.stringify(w));
    const next = cur === "" ? w : cur + " " + w;
    if (textWidth(next, size, face) <= maxW) {
      cur = next;
    } else {
      lines.push(cur);
      cur = w;
    }
  }
  if (cur !== "") lines.push(cur);
  if (lines.length > maxLines) {
    throw new Error("text overflows " + maxLines + " lines: " + JSON.stringify(text) + " -> " + lines.length);
  }
  return lines;
}

function drawLines(cv: Canvas, lines: string[], x: number, yTop: number, size: number, leading: number, c: RGB, face: string = "B"): void {
  for (let i = 0; i < lines.length; i++) {
    drawText(cv, lines[i], x, yTop + i * leading, size, c, face);
  }
}

function assertCharset(text: string): void {
  for (const ch of text) {
    if (ch === " ") continue;
    if (CHARSET.indexOf(ch) < 0) throw new Error("char outside font charset: " + JSON.stringify(ch) + " in " + JSON.stringify(text));
  }
}

